#[derive(Debug, Default)]
enum Nullable<T> {
    #[default]
    Omitted,
    Null,
    Value(T),
}

fn deserialize_nullable<'de, D, T>(deserializer: D) -> Result<Nullable<T>, D::Error>
where
    D: Deserializer<'de>,
    T: Deserialize<'de>,
{
    Option::<T>::deserialize(deserializer).map(|value| match value {
        Some(value) => Nullable::Value(value),
        None => Nullable::Null,
    })
}

#[derive(Debug, Serialize)]
#[serde(untagged)]
enum ItemResult<T> {
    Succeeded {
        request_id: Box<str>,
        value: T,
