                self.artifacts.clear();
                self.verified_base_digests.clear();
                self.admissions.clear();
                self.gated_wirings.clear();
                self.published_wirings.clear();
                self.publish_provenance = None;
                self.release = None;
            }
            DevStage::Admit => {
                self.admissions.clear();
                self.gated_wirings.clear();
                self.published_wirings.clear();
                self.publish_provenance = None;
                self.release = None;
            }
            DevStage::Gate => {
                self.gated_wirings.clear();
                self.published_wirings.clear();
                self.publish_provenance = None;
                self.release = None;
            }
            DevStage::Publish => {
                self.published_wirings.clear();
                self.publish_provenance = None;
                self.release = None;
            }
            DevStage::Apply | DevStage::Acl | DevStage::Release => {
                self.release = None;
            }
            DevStage::Activate => {}
        }
    }
}

