        "dock_id": {"type": "string", "pattern": UUID},
        "day": {"type": "string", "pattern": DAY},
        "status": {"type": ["string", "null"], "enum": STATUS + [None]},
    },
)

OPERATIONS = [
    ("carrier_create", "carrier.create", "dock:carrier/create@1.0.0",
     "/dock/carrier/create", CARRIER_CREATE),
    ("dock_create", "dock.create", "dock:dock/create@1.0.0",
     "/dock/dock/create", DOCK_CREATE),
    ("appointment_book", "appointment.book", "dock:appointment/book@1.0.0",
