        "package-id": "dock",
        "package-version": "1.0.0",
    },
    "component": "dock",
    "interface-version": "0.1.0",
    "operations": {
        registered: {
            "registered-operation": registered,
            "input-ports": [{"name": "input", "schema": schema}],
            "output-ports": [{"name": "main", "schema": {"type": "array"}}],
            "parameters": [],
        }
        for _, _, registered, _, schema in OPERATIONS
    },
    "connections": [],
}

(ROOT / "publication/components/dock.json.in").write_text(
