)

attachments = {}
for wiring_id, _, registered, path, schema in OPERATIONS:
    attachment_id = "dock-" + wiring_id.replace("_", "-") + "-http"
    definition = {
        "id": attachment_id,
        "kind": "http",
        "route": {"path": path, "method": "POST"},
